with by_dimension as (select d.region, src.status, count(*) as cnt, max(src.shipping_fee) as max_shipping_fee, round(avg(src.amount), 2) as avg_amount from orders src left join stores d on src.store_id = d.id group by grouping sets ((d.region, src.status), (d.region), ())) select region, cnt, avg_amount, case when region rlike '^(West|North)$' then 'GROUP_A' else 'EXTENDED' end as region_zone from by_dimension order by avg_amount desc nulls first
